using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;using TMPro;
public static class GridShiftV26UIExport {
 [MenuItem("GridShift/Objetos editáveis/Capturar interface atual do Play")]
 public static void CaptureCurrent(){if(!EditorApplication.isPlaying)throw new InvalidOperationException("Entre no Play e abra a interface que quer capturar.");Capture(SceneManager.GetActiveScene().name);}
 public static void Capture(string sceneName){Directory.CreateDirectory("Assets/Generated/Editable26");var root=new GameObject("Editable interface · "+sceneName);root.SetActive(false);var list=new List<GridShiftUILayout.View>();var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(c=>c.GetComponentInParent<GridShiftUILayout>()==null&&(c.transform.parent==null||c.transform.parent.GetComponentInParent<Canvas>()==null)).ToArray();
 foreach(var canvas in canvases){bool active=canvas.gameObject.activeSelf;canvas.gameObject.SetActive(false);GameObject copy=null;try{copy=UnityEngine.Object.Instantiate(canvas.gameObject,root.transform,false);copy.name=canvas.name;foreach(var b in copy.GetComponentsInChildren<MonoBehaviour>(true)){if(b==null)continue;if(b is UnityEngine.EventSystems.EventSystem||b is UnityEngine.EventSystems.BaseInputModule){UnityEngine.Object.DestroyImmediate(b);continue;}var ns=b.GetType().Namespace??"";if(ns.StartsWith("UnityEngine.UI")||ns.StartsWith("TMPro")||ns.StartsWith("UnityEngine.EventSystems"))continue;UnityEngine.Object.DestroyImmediate(b);}foreach(var camera in copy.GetComponentsInChildren<Camera>(true))UnityEngine.Object.DestroyImmediate(camera);foreach(var audio in copy.GetComponentsInChildren<AudioSource>(true))UnityEngine.Object.DestroyImmediate(audio);foreach(var field in copy.GetComponentsInChildren<TMP_InputField>(true))field.text="";foreach(var raw in copy.GetComponentsInChildren<RawImage>(true))if(raw.texture!=null&&!AssetDatabase.Contains(raw.texture))raw.texture=null;foreach(var node in copy.GetComponentsInChildren<Transform>(true)){var binding=node.gameObject.AddComponent<GridShiftUIElementBinding>();binding.originalName=node.name;}var cloned=copy.GetComponent<Canvas>();cloned.worldCamera=null;copy.SetActive(active);list.Add(new GridShiftUILayout.View{runtimeCanvas=canvas.name,source=cloned});}finally{canvas.gameObject.SetActive(active);}}
 var layout=root.AddComponent<GridShiftUILayout>();layout.views=list.ToArray();foreach(var r in root.GetComponentsInChildren<Renderer>(true))if(r is MeshRenderer){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++)if(mats[i]!=null&&!AssetDatabase.Contains(mats[i])){var m=UnityEngine.Object.Instantiate(mats[i]);AssetDatabase.CreateAsset(m,AssetDatabase.GenerateUniqueAssetPath("Assets/Generated/Editable26/UI-material.mat"));mats[i]=m;}r.sharedMaterials=mats;}
 string path="Assets/Generated/Editable26/UI-"+sceneName+".prefab";PrefabUtility.SaveAsPrefabAsset(root,path);UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();Directory.CreateDirectory("Docs/Validacao26");File.AppendAllText("Docs/Validacao26/ui-export.txt",sceneName+" canvases="+list.Count+"\n");}
 public static void Attach(Scene scene){string path="Assets/Generated/Editable26/UI-"+scene.name+".prefab";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(prefab==null)return;var existing=scene.GetRootGameObjects().FirstOrDefault(g=>g.GetComponent<GridShiftUILayout>()!=null);if(existing!=null)return;var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);go.SetActive(true);foreach(var canvas in go.GetComponentsInChildren<Canvas>(true))canvas.enabled=true;}
}

